from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/test-default")
async def test_default(x_header: str = Header()):
    return {"x_header": x_header}

@app.get("/test-alias-underscore")
async def test_alias_underscore(x_header: str = Header(alias="x_header")):
    return {"x_header": x_header}

@app.get("/test-alias-hyphen")
async def test_alias_hyphen(x_header: str = Header(alias="x-header")):
    return {"x_header": x_header}

@app.get("/test-no-convert")
async def test_no_convert(x_header: str = Header(alias="x_header", convert_underscores=False)):
    return {"x_header": x_header}

client = TestClient(app)

def test_default_underscore():
    # Should NOT accept x_header, should accept x-header
    response = client.get("/test-default", headers={"x_header": "val1"})
    assert response.json() == {"x_header": None}
    response = client.get("/test-default", headers={"x-header": "val2"})
    assert response.json() == {"x_header": "val2"}

def test_alias_underscore_default_convert():
    # convert_underscores=True by default. Should NOT accept x_header, should accept x-header
    response = client.get("/test-alias-underscore", headers={"x_header": "val1"})
    assert response.json() == {"x_header": None}
    response = client.get("/test-alias-underscore", headers={"x-header": "val2"})
    assert response.json() == {"x_header": "val2"}

def test_alias_hyphen():
    # Should accept x-header
    response = client.get("/test-alias-hyphen", headers={"x-header": "val1"})
    assert response.json() == {"x_header": "val1"}

def test_no_convert_underscore():
    # convert_underscores=False. Should accept x_header
    response = client.get("/test-no-convert", headers={"x_header": "val1"})
    assert response.json() == {"x_header": "val1"}

if __name__ == "__main__":
    try:
        test_default_underscore()
        test_alias_underscore_default_convert()
        test_alias_hyphen()
        test_no_convert_underscore()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)

